original_sql:
SELECT batsman, CAST(SUM(batsman_runs) AS REAL) * 100 / SUM(batsman_bowls_faced) AS strike_rate
FROM df
WHERE bowler = {bowler}
GROUP BY batsman
HAVING SUM(batsman_bowls_faced) >= 10
ORDER BY strike_rate DESC;

SELECT batsman, bowler, CAST(SUM(batsman_runs) AS REAL) * 100 / SUM(batsman_bowls_faced) AS strike_rate
FROM df
WHERE batsman = {batsman} AND bowler = {bowler}
GROUP BY batsman, bowler
HAVING SUM(batsman_bowls_faced) >= 10;

sql:
SELECT batsman, overs, batsman_runs, SUM(batsman_runs) OVER (PARTITION BY batsman ORDER BY overs) AS cumulative_runs_scored
FROM df
ORDER BY batsman, overs;

original_sql:
SELECT
  bowler,
  CASE WHEN SUM(bowler_bowls_done) > 0 THEN CAST(SUM(bowler_runs_given) AS REAL) * 100 / SUM(bowler_bowls_done) ELSE 0 END AS bowler_strike_rate
FROM df
WHERE bowler = {bowler}
GROUP BY bowler;

SELECT batsman, CAST(SUM(batsman_runs) AS REAL) * 100 / SUM(batsman_bowls_faced) AS strike_rate
FROM df
WHERE bowler = {bowler}
GROUP BY batsman
HAVING SUM(batsman_bowls_faced) > 0;

sql:
SELECT MAX(runs_in_over) AS max_runs_conceded_in_an_over
FROM (
  SELECT ceil(overs) as over_number, bowler, SUM(team_runs) AS runs_in_over
  FROM df
  GROUP BY ceil(overs), bowler
);

original_sql:
SELECT 
    batsman, 
    CASE WHEN sum(batsman_bowls_faced) = 0 THEN 0 ELSE CAST(sum(batsman_runs) AS REAL) * 100 / sum(batsman_bowls_faced) END AS strike_rate 
FROM df 
WHERE batsman = {batsman} 
GROUP BY batsman;

SELECT
  bowler,
  AVG(CAST(bowler_runs_given AS REAL) / bowler_bowls_done) AS avg_runs_per_ball
FROM df
WHERE bowler = {bowler}
GROUP BY bowler;

SELECT
  batsman,
  CAST(SUM(CASE WHEN batsman_runs = 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(overs) AS dot_ball_percentage
FROM df
WHERE batsman = {batsman}
GROUP BY batsman;

SELECT batsman, CASE WHEN CEIL(overs) <= 6 THEN 'Powerplay' WHEN CEIL(overs) > 6 AND CEIL(overs) <= 15 THEN 'Middle Overs' ELSE 'Death Overs' END AS phase, CASE WHEN SUM(batsman_bowls_faced) > 0 THEN CAST(SUM(batsman_runs) AS REAL) * 100 / SUM(batsman_bowls_faced) ELSE 0 END AS strike_rate
FROM df
WHERE batsman = {batsman}
GROUP BY batsman, phase
HAVING SUM(batsman_bowls_faced) > 10
ORDER BY CASE phase WHEN 'Powerplay' THEN 1 WHEN 'Middle Overs' THEN 2 WHEN 'Death Overs' THEN 3 END;

SELECT batsman, CAST(SUM(batsman_runs) AS REAL) * 100 / SUM(batsman_bowls_faced) AS batsman_strike_rate_vs_bowler
FROM df
WHERE bowler = {bowler}
GROUP BY batsman
HAVING SUM(batsman_bowls_faced) >= 10
ORDER BY batsman_strike_rate_vs_bowler DESC;

SELECT
  SUM(batsman_runs) AS total_runs_scored
FROM df
WHERE
  batsman = {batsman}
  AND bowler = {bowler};

SELECT
  COUNT(bowler_wickets) AS total_wickets
FROM df
WHERE
  bowler = {bowler}
  AND batsman = {batsman}
  AND bowler_wickets > 0;

sql:
select batsman, avg(runs_in_over) as avg_runs_per_over
from (
    select batsman, ceil(overs) as over_number, sum(batsman_runs) as runs_in_over
    from df
    group by batsman, over_number
) as batsman_over_runs
group by batsman
order by avg_runs_per_over desc;

